// Pure transcript helpers for the manual sermon highlights pilot.
// All clip times are derived from ASR segment timestamps, never generated by the LLM.

export function normalizeSegments(raw, offsetSeconds, durationSeconds) {
  if (!Array.isArray(raw)) throw new Error("transcription_segments_missing");
  return raw.flatMap((item) => {
    const start = Number(item?.start), end = Number(item?.end);
    const text = typeof item?.text === "string" ? item.text.trim().replace(/\s+/g, " ") : "";
    if (!text || !Number.isFinite(start) || !Number.isFinite(end) ||
        start < 0 || end <= start || start > durationSeconds + 2) return [];
    return [{
      start: Math.round((offsetSeconds + start) * 100) / 100,
      end: Math.round((offsetSeconds + Math.min(end, durationSeconds + 2)) * 100) / 100,
      text,
    }];
  });
}

export function transcriptWindows(segments, windowSeconds = 600, overlapSeconds = 90) {
  if (!segments.length) return [];
  const last = segments[segments.length - 1].end;
  const windows = [];
  for (let from = 0; from < last; from += windowSeconds) {
    const group = segments.flatMap((s, id) =>
      s.end >= from - overlapSeconds && s.start < from + windowSeconds + overlapSeconds
        ? [{ id, ...s }] : []);
    if (group.length) windows.push(group);
  }
  return windows;
}

export function formatTime(seconds) {
  const n = Math.max(0, Math.floor(seconds));
  return String(Math.floor(n / 60)).padStart(2, "0") + ":" +
    String(n % 60).padStart(2, "0");
}

export function highlightPrompt(window) {
  const transcript = window.map((s) =>
    `[${s.id}] ${formatTime(s.start)}-${formatTime(s.end)} ${s.text}`).join("\n");
  return [
    "You are assisting a church editor. Find up to THREE powerful, biblically faithful",
    "standalone excerpts of approximately 30-90 seconds from the TIMESTAMPED TRANSCRIPT.",
    "Prefer coherent ideas, Scripture explanation, encouragement and memorable applications.",
    "Avoid clips requiring missing context, jokes that could be misunderstood, altar calls,",
    "private information, or claims that sound misleading when isolated.",
    "You may return zero highlights if this portion has no suitable excerpts.",
    "Choose existing START and END segment IDs, inclusive. Do not invent timestamps,",
    "quote text, segment IDs or theological assertions. Rate quality from 1 to 5,",
    "where 5 is most useful. Keep titles and reasons brief.",
    "Return a JSON object containing only a highlights array with:",
    "start_segment (integer), end_segment (integer), title (string), reason (string), score (integer).",
    "",
    transcript
  ].join("\n");
}

export const HIGHLIGHT_SCHEMA = {
  type: "object",
  properties: {
    highlights: {
      type: "array",
      items: {
        type: "object",
        properties: {
          start_segment: { type: "integer" },
          end_segment: { type: "integer" },
          title: { type: "string" },
          reason: { type: "string" },
          score: { type: "integer" },
        },
        required: ["start_segment", "end_segment", "title", "reason", "score"],
      },
    },
  },
  required: ["highlights"],
};

export function parseHighlightCandidates(output, window) {
  let result = output?.response ?? output;
  if (typeof result === "string") {
    try { result = JSON.parse(result); } catch { throw Error("invalid_highlight_json"); }
  }
  if (!Array.isArray(result?.highlights)) throw Error("invalid_highlight_response");
  const lookup = new Map(window.map((s) => [s.id, s]));
  const candidates = [];
  for (const item of result.highlights.slice(0, 8)) {
    const a = item?.start_segment, b = item?.end_segment;
    if (!Number.isInteger(a) || !Number.isInteger(b) || b < a) continue;
    const start = lookup.get(a), end = lookup.get(b);
    if (!start || !end || end.end - start.start < 25 || end.end - start.start > 105) continue;
    const title = typeof item.title === "string" ? item.title.trim().slice(0, 100) : "";
    const reason = typeof item.reason === "string" ? item.reason.trim().slice(0, 240) : "";
    if (!title || !reason) continue;
    const excerpt = window.filter((s) => s.id >= a && s.id <= b)
      .map((s) => s.text).join(" ");
    if (!excerpt.trim()) continue;
    candidates.push({
      start: start.start, end: end.end, title, reason, excerpt,
      score: Math.max(1, Math.min(5, Number(item.score) || 1)),
    });
  }
  return candidates;
}

export function selectHighlights(candidates, limit = 5) {
  const sorted = [...candidates].sort((a, b) =>
    b.score - a.score || a.start - b.start);
  const chosen = [];
  for (const candidate of sorted) {
    if (chosen.some((previous) =>
      Math.min(previous.end, candidate.end) - Math.max(previous.start, candidate.start) > 10)) continue;
    chosen.push(candidate);
    if (chosen.length >= limit) break;
  }
  return chosen.sort((a, b) => a.start - b.start)
    .map((candidate, index) => ({ ...candidate, number: index + 1 }));
}
